    case '**': return left ** right;
    case '//': {
      const quotient = Math.trunc(left / right);
      return quotient === 0 ? 0 : quotient;
    }
    case '%': {
      const remainder = left % right;
      if (remainder === 0) return 0;
      return remainder;
    }
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
